/// <summary>
/// This method disable the update sales lines pop up
/// </summary>
public void write()
{
    SalesTable      salesTable          = this.cursor();
    CurrencyCode    targetCurrency      = salesTable.CurrencyCode;
    CurrencyCode    originalCurrency    = salesTable.orig().CurrencyCode;
    GUPParameters   gUPParameters       = GUPParameters::find();

    if(gUPParameters.METSuppressPriceUpdate)
    {
        salesTable.CurrencyCode = originalCurrency;
    }

    next write();

    if(gUPParameters.METSuppressPriceUpdate)
    {
        if (targetCurrency != originalCurrency)
        {
            ttsbegin;
            SalesTable salesTableUpdate = SalesTable::find(salesTable.SalesId, true);

            if (salesTableUpdate)
            {
                salesTableUpdate.CurrencyCode = targetCurrency;
                salesTableUpdate.doUpdate();
            }
            ttscommit;
        }
    }

}
